<?php
namespace App\Controllers;
use App\Application\Services\MaintenanceService;
class MaintenanceController extends BaseController {
 public function index(){return view('maintenance/index',['title'=>'Maintenance','rows'=>db_connect()->table('maintenance_records m')->select('m.*,e.asset_code,e.name equipment_name,u.display_name reporter')->join('equipment e','e.id=m.equipment_id')->join('users u','u.id=m.reported_by','left')->orderBy('m.created_at','DESC')->get()->getResultArray(),'equipment'=>$this->repository()->equipment()]);}
 public function store(){if(!$this->validate(['equipment_id'=>'required|is_natural_no_zero','maintenance_type'=>'required|max_length[100]','description'=>'required|max_length[3000]','quantity'=>'required|is_natural_no_zero','status'=>'required|in_list[reported,scheduled,in_progress]','start_date'=>'permit_empty|valid_date[Y-m-d]','cost'=>'permit_empty|decimal|greater_than_equal_to[0]']))return redirect()->back()->withInput()->with('errors',$this->validator->getErrors());try{(new MaintenanceService($this->repository()))->create(['equipment_id'=>$this->postPositiveInt('equipment_id'),'maintenance_type'=>$this->postString('maintenance_type'),'description'=>$this->postString('description'),'quantity'=>$this->postPositiveInt('quantity'),'status'=>$this->postString('status'),'start_date'=>$this->postString('start_date')?:null,'completion_date'=>null,'cost'=>$this->postString('cost')?:null,'notes'=>$this->postString('notes')?:null],$this->userId());return redirect()->back()->with('success','Maintenance record created.');}catch(\Throwable $e){return redirect()->back()->withInput()->with('error',$this->safeErrorMessage($e,'Maintenance record could not be created.'));}}
 public function status(int $id){try{(new MaintenanceService($this->repository()))->updateStatus($id,$this->postString('status'),$this->userId());return redirect()->back()->with('success','Maintenance status updated.');}catch(\Throwable $e){return redirect()->back()->with('error',$this->safeErrorMessage($e,'Maintenance status could not be updated.'));}}
}
